package fs

import (
	"context"
	"io"
	"sync"
	"testing"
	"time"

	"go.flipt.io/flipt/internal/containers"
	"go.uber.org/zap"
)

// UpdateFunc checks for changes and reports whether the snapshot was modified.
type UpdateFunc func(context.Context) (bool, error)

var _ io.Closer = (*Poller)(nil)

type Poller struct {
	logger *zap.Logger
	ctx    context.Context
	cancel context.CancelFunc
	update UpdateFunc

	mu      sync.Mutex
	running bool
	closed  bool
	done    chan struct{}

	interval time.Duration
	notify   func(modified bool)
}

func WithInterval(interval time.Duration) containers.Option[Poller] {
	return func(p *Poller) {
		p.interval = interval
	}
}

func WithNotify(t *testing.T, n func(modified bool)) containers.Option[Poller] {
	t.Helper()
	return func(p *Poller) {
		p.notify = n
	}
}

func NewPoller(ctx context.Context, logger *zap.Logger, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	ctx, cancel := context.WithCancel(ctx)
	p := &Poller{
		logger:   logger,
		ctx:      ctx,
		cancel:   cancel,
		update:   update,
		done:     make(chan struct{}),
		interval: 30 * time.Second,
	}
	containers.ApplyAll(p, opts...)
	return p
}

// Poll runs the common polling strategy until the poller is closed or its parent context ends.
func (p *Poller) Poll() {
	p.mu.Lock()
	if p.closed || p.running {
		p.mu.Unlock()
		return
	}
	p.running = true
	p.mu.Unlock()
	defer close(p.done)

	ticker := time.NewTicker(p.interval)
	defer ticker.Stop()
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			if p.ctx.Err() != nil {
				return
			}
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

// Close stops polling and waits for any in-flight update to finish.
func (p *Poller) Close() error {
	p.mu.Lock()
	p.closed = true
	p.cancel()
	running := p.running
	p.mu.Unlock()
	if running {
		<-p.done
	}
	return nil
}
